-- Supplement Littérature Universelle NS1-NS3 (matiere_id=20)
-- ATTENTION : NS1, NS2, NS3 SEULEMENT — aucun chapitre NS4
-- Objectif : porter chaque chapitre à ≥ 20 questions

DO $$
DECLARE chap_id INTEGER;
BEGIN
  SELECT id INTO chap_id FROM chapitres WHERE matiere_id = 20 AND titre = 'Les grands genres littéraires et leurs caractéristiques' AND niveau_v4 = 'NS1';
  IF chap_id IS NOT NULL THEN
  END IF;
END $$;

